let products = [], category = 'All', bag = {};
const $ = id => document.getElementById(id);
const money = n => new Intl.NumberFormat('en-IN', {style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
try { const saved=JSON.parse(localStorage.getItem('maezy-bag')||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) bag=saved; } catch {}
const escapeHTML = str => String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('maezy-bag',JSON.stringify(bag));}catch{}$('bag-count').textContent=Object.values(bag).reduce((a,b)=>a+b,0);}
function render(){const q=$('search').value.toLowerCase().trim();let found=products.filter(p=>(category==='All'||p.category===category)&&`${p.name} ${p.description}`.toLowerCase().includes(q));if($('sort').value==='low')found.sort((a,b)=>a.price-b.price);if($('sort').value==='high')found.sort((a,b)=>b.price-a.price);$('result-count').textContent=`${found.length} ${found.length===1?'piece':'pieces'} · Pre-launch catalogue`; $('products').innerHTML=found.length?found.map(p=>`<button class="product-card" data-product="${p.id}"><img loading="lazy" src="${p.image}" alt="${escapeHTML(p.name)}"><span class="product-meta">${p.category}</span><span class="product-name">${escapeHTML(p.name)}</span><span class="product-price">${money(p.price)} <small>MRP</small></span><span class="view-piece">View piece ↗</span></button>`).join(''):'<p class="empty">No pieces match your search. Try another colour or name.</p>';}
function showProduct(id){const p=products.find(p=>p.id===id);if(!p)return; $('product-detail').innerHTML=`<img src="${p.image}" alt="${escapeHTML(p.name)}"><div class="detail-copy"><span class="eyebrow">${p.category} · PRE-LAUNCH</span><h2 id="product-title">${escapeHTML(p.name)}</h2><p class="detail-price">${money(p.price)} <small>MRP</small></p><p>${escapeHTML(p.description)}</p>${p.size?`<p><b>Ring size:</b> ${p.size}</p>`:''}<p class="catalogue-note">From the pre-launch catalogue. Please confirm current availability before ordering.</p><button class="button" data-add="${p.id}">ADD TO BAG +</button><p class="checkout-note">Explore and save your favourites. Online checkout is coming soon.</p></div>`;$('product-dialog').showModal();}
function renderBag(){const entries=products.filter(p=>bag[p.id]);$('bag-items').innerHTML=entries.length?entries.map(p=>`<div class="bag-row"><img src="${p.image}" alt="${escapeHTML(p.name)}"><div><h3>${escapeHTML(p.name)}</h3><p>${money(p.price)}</p><div class="quantity"><button aria-label="Decrease quantity of ${escapeHTML(p.name)}" data-change="${p.id}" data-delta="-1">−</button><span>${bag[p.id]}</span><button aria-label="Increase quantity of ${escapeHTML(p.name)}" data-change="${p.id}" data-delta="1" ${bag[p.id]>=10?'disabled':''}>+</button><button data-remove="${p.id}">Remove</button></div></div></div>`).join(''):'<p>Your bag is waiting for something beautiful.</p>';$('bag-summary').innerHTML=entries.length?`<div class="subtotal"><span>Catalogue subtotal</span><strong>${money(entries.reduce((sum,p)=>sum+p.price*bag[p.id],0))}</strong></div><p class="checkout-note">Shipping and any applicable adjustments are not calculated. No pre-launch discount has been applied.</p>`:'';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.product)showProduct(b.dataset.product);if(b.dataset.add){bag[b.dataset.add]=Math.min(10,(bag[b.dataset.add]||0)+1);persist();$('toast').textContent='Saved to your bag';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').textContent='',2500);}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));render();}if(b.dataset.change){const id=b.dataset.change;bag[id]=Math.max(0,Math.min(10,bag[id]+Number(b.dataset.delta)));if(!bag[id])delete bag[id];persist();renderBag();}if(b.dataset.remove){delete bag[b.dataset.remove];persist();renderBag();}if(b.classList.contains('close'))b.closest('dialog').close();});
$('open-bag').addEventListener('click',()=>{renderBag();$('bag-dialog').showModal();});$('search').addEventListener('input',render);$('sort').addEventListener('change',render);
fetch('products.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{products=data;bag=Object.fromEntries(Object.entries(bag).filter(([id,n])=>products.some(p=>p.id===id)&&Number.isInteger(n)&&n>0&&n<=10));persist();render();}).catch(()=>{$('result-count').textContent='The catalogue could not load. Please refresh to try again.';});
